        }
    }

    proof fn lemma_pow_mod_step(b: int, i: int, m: int)
        requires m > 1, i >= 0
        ensures spec_pow_mod(b, i + 1, m) == (b * spec_pow_mod(b, i, m)) % m
    {
    }
'''
code = '''
    {
        let mut cur: u64 = 1;
        let mut i: u64 = 0;
        while i < p
            invariant
                p > 1,
                0 <= i <= p,
                cur as int == spec_pow_mod(g as int, i as int, p as int),
                forall |k: int| 0 <= k < i ==> !is_discrete_log(g as int, h as int, p as int, k),
            decreases p - i
        {
            if cur == h % p {
                return Some(i);
            }
            proof {
                lemma_pow_mod_bounds(g as int, i as int, p as int);
                lemma_pow_mod_step(g as int, i as int, p as int);
            }
