            assert(prod <= (u64::MAX as u128) * (u64::MAX as u128)) by (nonlinear_arith)
                requires prod == (cur as u128) * (g as u128), cur <= u64::MAX, g <= u64::MAX;
            cur = ((prod % (p as u128)) as u64);
            i = i + 1;
        }
        None
    }
